describe("가격 흐름의 시작", () => {
	// 10/28에 시작가 195,000으로 그은 직선. 10/28·10/29 두 번 건너뛰어 지금도 195,000이다.
	const start = { price: 195_000, date: "2026-10-28" };
	const path = pricePath(start, 100_000, "2026-11-10", "2026-10-29");

	test("오늘 직선 가격은 지금 가격보다 낮다", () => {
		expect(path[0]).toEqual({ date: "2026-10-29", price: 180_000 });
	});

	test("오늘이 지금과 다르면 맨 앞에 지금 가격이 붙는다", () => {
		const flow = flowFromNow(195_000, path);
		expect(flow[0]).toEqual({ date: "2026-10-29", price: 195_000, current: true });
		expect(flow.slice(1)).toEqual(path);
	});

	test("오늘이 지금과 같으면 그대로다", () => {
		expect(flowFromNow(180_000, path)).toEqual(path);
		expect(flowFromNow(180_000, [])).toEqual([]);
	});
});

