function bumpOne(
	serial: string,
	exec: AdbExec,
	ops: ScreenOp[],
	item: BatchItem,
	dry: boolean,
	book?: BumpBook,
): "bump" | "skip" | "stop" {
	const title = item.title;
	const price = item.proposedPrice;
	if (stopRequested()) return "stop";
	let sheet: string | null = null;
	// 탭이 움직이는 목록에 떨어져 창이 안 열릴 수 있다. 멈춘 화면을 다시 읽어 한 번 더 누른다.
	for (let attempt = 0; attempt < 2 && !sheet; attempt++) {
		const xml = attempt === 0 ? dumpXml(serial, exec) : settledXml(serial, exec);
		const node = cardBump(parseNodes(xml), title);
		if (!node) return "skip";
		const point = center(node);
		tap(
			serial,
			exec,
			ops,
			point.x,
			point.y,
			"카드 끌어올리기",
			`「${title}」을 ${price.toLocaleString("ko-KR")}원으로 끌어올리려고`,
		);
		if (stopRequested()) return "stop";
		sheet = waitFor(serial, exec, (text) => onBumpSheet(text) || cooldownTip(text), attempt === 0 ? 3000 : 8000);
	}
	if (!sheet || cooldownTip(sheet)) {
		nowCooldown(item.id, sheet, book);
		backToSales(serial, exec, ops);
		return "skip";
	}
	// 목록이 다시 그려지는 사이 다른 카드를 눌렀을 수 있다. 연 창의 제목이 다르면 아무것도 바꾸지 않고 닫는다.
	if (!showsTitle(sheet, title)) {
		noteSkip(title, "연 끌어올리기 창의 제목이 달라서");
		backToSales(serial, exec, ops);
		return "skip";
	}
	const ready = ensurePrice(serial, exec, ops, sheet, price, dry);
	if (ready === "stop") return "stop";
	if (dry) {
		backToSales(serial, exec, ops);
		return ready === "skip" ? "skip" : "bump";
	}
	if (ready === "skip") {
		backToSales(serial, exec, ops);
		return "skip";
	}
	// 가격을 하나도 확정하지 않은 채로 멈춘다. 그만두기를 먼저 누른다.
	if (stopRequested()) {
		backToSales(serial, exec, ops);
		return "stop";
	}
	if (
		!confirmMatchingPrice(
			serial,
			exec,
			ops,
			price,
			CONFIRM_BUMP,
			`「${title}」 ${price.toLocaleString("ko-KR")}원 확정`,
		)
	) {
		backToSales(serial, exec, ops);
		return "stop";
	}
	recordBumped(item.id, book);
	backToSales(serial, exec, ops);
	return "bump";
}

function priceOne(
	serial: string,
	exec: AdbExec,
	ops: ScreenOp[],
	item: BatchItem,
	dry: boolean,
): "price" | "skip" | "stop" {
	const title = item.title;
	const price = item.proposedPrice;
	if (stopRequested()) return "stop";
	let menu: string | null = null;
	// 탭이 움직이는 목록에 떨어져 메뉴가 안 열릴 수 있다. 멈춘 화면을 다시 읽어 한 번 더 누른다.
	for (let attempt = 0; attempt < 2 && !menu; attempt++) {
		const xml = attempt === 0 ? dumpXml(serial, exec) : settledXml(serial, exec);
		const more = moreFor(parseNodes(xml), title);
		if (!more) return "skip";
		const at = center(more);
		tap(serial, exec, ops, at.x, at.y, "더보기", `「${title}」 가격만 ${price.toLocaleString("ko-KR")}원으로 맞추려고`);
		menu = waitFor(serial, exec, (text) => text.includes("게시글 수정"), 4000);
	}
	if (!menu) {
		backToSales(serial, exec, ops);
		return "skip";
	}
	const edit = parseNodes(menu).find((node) => node.text === "게시글 수정");
	if (!edit || forbiddenLabel(edit.text, edit.desc)) {
		backToSales(serial, exec, ops);
		return "stop";
	}
	const editAt = center(edit);
	tap(serial, exec, ops, editAt.x, editAt.y, "게시글 수정", `「${title}」 수정 창을 열려고`);
	const form = scrollToEditPrice(serial, exec, ops);
	if (!form) {
		noteSkip(title, "수정 창에서 가격 칸을 못 찾아서");
		backToSales(serial, exec, ops);
		return "skip";
	}
	const ready = ensurePrice(serial, exec, ops, form, price, dry, true);
	if (ready === "stop") {
		backToSales(serial, exec, ops);
		return "skip";
	}
	if (dry) {
		backToSales(serial, exec, ops);
		return ready === "skip" ? "skip" : "price";
	}
	if (ready === "skip") {
		backToSales(serial, exec, ops);
		return "skip";
	}
	if (stopRequested()) {
		backToSales(serial, exec, ops);
		return "stop";
	}
	if (
		!confirmMatchingPrice(
			serial,
			exec,
			ops,
			price,
			CONFIRM_EDIT,
			`「${title}」 ${price.toLocaleString("ko-KR")}원 저장`,
		)
	) {
		backToSales(serial, exec, ops);
		return "stop";
	}
	backToSales(serial, exec, ops);
	return "price";
}

/** 성공한 끌어올리기의 횟수·쿨타임을 남긴다. 횟수는 이전+1, 다음 시각은 추정표. */
function recordBumped(listingId: string, book?: BumpBook) {
	if (!book) return;
	const bumpedAt = new Date().toISOString();
	const bumpCount = book.previousBumpCount(listingId) + 1;
	book.recordBump(listingId, { bumpedAt, bumpCount, nextBumpAt: nextBumpAt(bumpedAt, bumpCount) });
}

/** 폰에 뜬 남은 시간 문구를 읽어 다음 끌어올림 시각을 남긴다. 문구를 못 읽으면 아무것도 하지 않는다. */
function nowCooldown(listingId: string, xml: string | null, book?: BumpBook) {
	if (!book || !xml) return;
	const text = cooldownText(xml);
	if (!text) return;
	const next = parseCooldownText(text, new Date());
	if (next) book.recordCooldown(listingId, next);
}

/** 화면에서 쿨타임 문구를 꺼낸다. 판매팁·끌어올릴 수 있어요 문구가 있는 노드 중 가장 긴 글. */
export function cooldownText(xml: string): string | null {
	const texts = parseNodes(xml)
		.flatMap((node) => [node.text, node.desc])
		.filter((text) => text !== "" && cooldownTip(text))
		.sort((left, right) => right.length - left.length);
	return texts[0] ?? null;
}

function scrollToEditPrice(serial: string, exec: AdbExec, ops: ScreenOp[]): string | null {
	let prev = "";
	for (let page = 0; page < 8; page++) {
		if (stopRequested()) return null;
		const xml = dumpXml(serial, exec);
		if (editPriceReady(parseNodes(xml), CONFIRM_EDIT)) return xml;
		const key = parseNodes(xml)
			.map((node) => node.text)
			.filter(Boolean)
			.slice(0, 8)
			.join("|");
		if (page > 0 && key !== "" && key === prev) return null;
		prev = key;
		swipeStep(serial, exec, ops, "가격 칸이 아직 안 보여서");
	}
	return null;
}

